def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this function is called recursively to update a partial ``last_applied_manifest`` from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in last_applied_manifest if they are not yet present

    """
    for observed_field in observer_schema:
        if observed_field not in response:
            raise KeyError(f"{observed_field} is not present in the Kubernetes response")
        if observed_field not in last_applied_manifest:
            last_applied_manifest[observed_field] = {}
        if isinstance(response[observed_field], dict):
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[observed_field],
                observer_schema[observed_field],
                response[observed_field])
        else:
            last_applied_manifest[observed_field] = response[observed_field]
    return last_applied_manifest

