    if stream is not None and Duemper is None:
        stream.write(data)
    elif stream is not None and Dumper is not None:
        stream = Dumper.open(stream, mode='w',)}
        kws.get('canonical', Dumper.canonical)
        kws.get('indent', Dumper.indent)
        kws.get('width', Dumper.width)
        kws.get('allow_unicode', Dumper.allow_unicode)
        kws.get('line_break', Dumper.line_break)
        kws.get('encoding', Dumper.encoding)
        kws.get('explicit_start', Dumper.explicit_start)
        kws.get('explicit_end', Dumper.explicit_end)
