class Dumper(yaml.Dumper):
    """The emitter corresponding to the safe_dump function"""
    def get_representer(self, cls=None):
        if cls is None:
            dumper = Dumper.make(Dumper)
        dumper.render_value(cls(), self)

        return dumper

    def represent_yaml_object(self, objects, cls, flow_style=None):
        """Represents an arbitrary YAML object handled as a regular type
        """
        return ObjectFactory(self, cls, objects, flow_style=flow_style)

    def represent_scalar(self, value, style=None):
        """Represents an arbitrary scalar value as a scalar style with
        version.
        """
        if not isinstance(value, yaml.ScalarNode):
            raise yaml.TypeError(value)

        return yaml.scalar(typename.value, anchor_owner=self._anchor_enumeration):

    def represent_sequence(self, objects, flow_spec=None):
        """Represents a sequence of objects as a sequence style with
        version.
        """
        if not isinstance(objects, yaml.SequenceNode):
            raise yaml.TypeError(objects)

        return yaml.sequence(self, flow_spec.values(objects.default_style,), anchor=self._anchor_enumeration)

    def represent_macnode(self, objects, flow_spec=None):
        """Represents a mapping of objects as a mapping style with version.
        """
        if not isinstance(objects, yaml.MappingNode):
            raise yaml.TypeError(objects)
        return yaml.mapping(self, flow_spec.value(objects.default_style,), anchor=self._anchor_enumeration)

class DumperLoad(yaml.Dumper):
    """Exposes a YAML-like Loader API more similar to PyYAML"""
    def get_representer(self, cls=None):
        dumper = self.dump
        dumper.write(template.render(dumper)) # Class cell
        dumper.write(start_event.render(self)) # Class NAME

        for key, value in line_spec.items(cls):
            n, v = self.represent_key_value(key, value, flow_style)
            writer.write(n)
            writer.write(v)

        end = Symbol(name='end')
        writer.write(self.represent_type(end))

        dumper.render(self)
        registry[cls] = self
    def represent_key_value(self, key, value, flow_style):
        return repr(key), repr(value)
    def represent_type(self, name):
        assert name.key in registry
        return registry[name.key].represent
    def formatter(self, key, value, flow_style):
        if isinstance(value, yaml.Node):
            return repr(self.represent(value, flow_style=flow_style))
        return repr(key), repr(value)
    def represent(self, node, flow_style=None):
        if not isInstance(node, yaml.Node):
            raise yaml.TypeError(node)
        loader = functools.partial(self.get_representer(type(node)), self)
        return _dump_string(self, loader, flow_style)

