def load_configurations(config_filenames, overrides=None, resolve_env=True):
    configs = {}
    logger = logging.getLogger(__name__)
    records = []
    for config_filename in config_filenames:
        try:
            configs[config_filename] = _load_config(config_filename, overrides, resolve_env)
        except (ValueError, KeyError) as e:
            records.append(logging.LogRecord(logger.name, logging.ERROR, config_filename, 0, e))
    return configs, records

def _load_config(config_filename, overrides=None, resolve_env=True):
    config = _parse_config(config_filename, resolve_env)
    if overrides:
        for key, val in overrides.items():
            config[key] = val
    _validate_config(config)
    return config

def _parse_config(config_filename, resolve_env=True):
    if resolve_env:
        config = _resolve_env_vars(config_filename)
    else:
        config = _read_config(config_filename)
    return config

def _resolve_env_vars(config_filename):
    # Load the configuration file and resolve any environment variables
    with open(config_filename) as fd:
        config = json.load(fd)
    resolved_config = {}
    for key, val in config.items():
        if isinstance(val, str) and val.startswith('$'):
            resolved = os.environ.get(val[1:], val)
            config[key] = resolved
    return config

def _validate_config(config):
    # Validate the configuration values to ensure they are valid
    if not isinstance(config, dict):
        raise ValueError(f"Configuration is not a dictionary: {config}")
    for key, val in config.items():
        if key not in _VALID_KEYS:
            raise KeyError(f"Invalid key in configuration: {key}")
        if val not in _VALID_VALS:
            raise ValueError(f"Invalid value in configuration: {val}")
    return config
