def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """ Convert a histogram to a graph """
    if not isinstance(hist, *histogram_types) or (
        make_value is not None and not callable(make_value)
    ):
        raise TypeError("hist must be a histogram and make_value a function")

    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")

    if not isinstance(field_names, tuple) or len(field_names) < 1:
        raise TypeError("field_names must be tuple with at least one element")

    if scale and not isinstance(scale, *scales):
        raise TypeError("scale must be a scale")

    if hist.is_integer:
        bin_values = [bin_.midpoint for bin_ in hist]
    else:
        bin_values = [bin_.left for bin_ in hist]

    # Create graph with empty fields
    graph = Graph(
        field_names=field_names,
        scale=scale or hist.scale,
        normalizable=hist.normalizable,
    )

    # Add points to graph
    for bin_value in bin_values:
        point_value = make_value(bin_value) if make_value else bin_.content
        point = Point(
            value=point_value,
            coordinate=get_coordinate(bin_value),
            # Add context if any
            context=bin_.context if "context" in dir(bin_) else None,
        )
        graph.add_point(point)

    return graph
