def verifyClass(iface, candidate, tentative=False):
    if not iface:
        raise ValueError("Interface cannot be empty")
    if not candidate:
        raise ValueError("Candidate cannot be empty")
    if not tentative:
        iface.verify(candidate)
    else:
        if iface.type() == "duck" and candidate.type() == "duck":
            return True
        else:
            return False
    if iface.methods:  # assess method exportation
        for method in iface.methods:
            if method not in candidate.methods:
                return False
            if not tentative:
                iface.verify(candidate.methods[method])
            else:
                if candidate.methods[method](1) != 1:
                    return False
    else:  # no methods, simply return True
        return True

def verifyClass(self):
    if not self.type():
        raise ValueError("Class cannot be empty")
    self.verify(self)
    if self.type() == "duck":
        return True
    else:
        return False
    if self.methods:  # assess method exportation
        for method in self.methods:
            if method not in self.methods:
                return False
            if not tentative:
                self.verify(self.methods[method])
            else:
                if self.methods[method](1) != 1:
                    return False
    else:  # no methods, simply return True
        return True

def verifyClass(self, *args):
    if not self.type():
        raise ValueError("Class cannot be empty")
    self.verify(self, *args)
    if self.type() == "duck":
        return True
    else:
        return False
    if self.methods:  # assess method exportation
        for method in self.methods:
            if method not in self.methods:
                return False
            if not tentative:
                self.verify(self.methods[method], *args)
            else:
                if self.methods[method](1) != 1:
                    return False
    else:  # no methods, simply return True
        return True

def determineMetaclass(bases, explicit_mc=None):
    """Return metaclass for given bases and explicit __metaclass__

    :param bases: Sequence of base classes
    :type bases: sequence of types
    :param explicit_mc: Explicit metaclass, defaults to None
    :type explicit_mc: type or None
    :returns: Metaclass for bases and explicit __metaclass__
    :rtype: type
    """
    # Check if explicit metaclass is passed or defined
    if explicit_mc is None:
        for base in bases:
            try:
                for mc in base.__metaclass__:
                    return mc
            except AttributeError:
                continue
        # If no explicit metaclass found, return type(top ancestor)
        return type(bases[0])
    else:
        # Explicit metaclass is passed, return it
        return explicit_mc

