def parse_diaspora_webfinger(document: str) -> Dict[str, Any]:
    result = {}
    if document.startswith("<xrd"):
        root = etree.fromstring(document)
        for service in root.findall(".//{*}Service"):
            props = service.attrib.get("Properties")
            for prop in props.split(" "):
                key, value = prop.split("=", 1)
                result[key] = value
    else:
        result = json.loads(document)
    return result
